fn compile_bpf(veth_ifindex: u32) -> Result<()> {
    let mut src = String::new();
    write!(
        &mut src,
        r#"#include <linux/bpf.h>
#include <linux/if_ether.h>
#include <linux/ipv6.h>
#include <bpf/bpf_helpers.h>
#include <bpf/bpf_endian.h>

#define VETH {veth_ifindex}

SEC("xdp")
int xdp_steer(struct xdp_md *ctx) {{
    void *de = (void *)(long)ctx->data_end;
    void *da = (void *)(long)ctx->data;
    struct ethhdr *h = da;
    if (da + sizeof(*h) > de) return XDP_PASS;
    if (h->h_proto != bpf_htons(0x86DD)) return XDP_PASS;
    struct ipv6hdr *ip = da + sizeof(*h);
    if ((void *)ip + sizeof(*ip) > de) return XDP_PASS;
    __u8 ct[16] = {{0x26,0x07,0x53,0x00,0x02,0x05,0x02,0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x5b,0xc7}};
    if (__builtin_memcmp(&ip->daddr, ct, 16) == 0) return bpf_redirect(VETH, 0);
    return XDP_PASS;
}}
char _license[] SEC("license") = "GPL";
"#
    )
    .expect("write BPF source");

    fs::create_dir_all(BPF_DIR).with_context(|| format!("create {}", BPF_DIR))?;
    fs::write(BPF_C_PATH, src).with_context(|| format!("write {}", BPF_C_PATH))?;
    // -g generates BTF info required by libxdp multiprog dispatcher
    run(
        "clang",
        [
            "-O2", "-g", "-target", "bpf", "-c", BPF_C_PATH, "-o", BPF_O_PATH,
        ],
    )
}

fn configure_tc() -> Result<()> {
    run_ignore("tc", ["qdisc", "del", "dev", HOST_IF, "clsact"]);
    run("tc", ["qdisc", "add", "dev", HOST_IF, "clsact"])?;

    // Use tc mirred egress mirror to duplicate (dup) traffic to the veth.
    // This is separate from the D-Bus tree mirror.
    for t in ["133", "134", "135", "136"] {
        run(
            "tc",
            [
                "filter", "add", "dev", HOST_IF, "ingress", "protocol", "ipv6", "pref", "1",
                "flower", "ip_proto", "icmpv6", "type", t, "action", "mirred", "egress", "mirror",
                "dev", VETH,
            ],
        )?;
    }

    run(
        "tc",
        [
            "filter", "add", "dev", HOST_IF, "ingress", "protocol", "ipv6", "pref", "2", "flower",
            "ip_proto", "udp", "dst_port", "546", "action", "mirred", "egress", "mirror", "dev",
            VETH,
        ],
    )?;
    run(
        "tc",
        [
            "filter", "add", "dev", HOST_IF, "ingress", "protocol", "ipv6", "pref", "2", "flower",
            "ip_proto", "udp", "dst_port", "547", "action", "mirred", "egress", "mirror", "dev",
            VETH,
        ],
    )?;

    Ok(())
}

fn configure_container_network(_ct_pid: u32) -> Result<()> {
    // Container IPv4/IPv6 addresses are managed by systemd-networkd inside the
    // container via eth0.network (static config). Only host-side state is set here.
    run(
        "sysctl",
        [&format!("net.ipv6.conf.{}.proxy_ndp=1", HOST_IF)],
    )?;
    run("sysctl", ["-w", "net.ipv6.conf.all.forwarding=1"])?;
    run("ip", ["addr", "add", "10.200.0.2/30", "dev", VETH])
        .unwrap_or_else(|e| warn!("Failed to add IPv4 to {}: {}", VETH, e));
    run(
        "ip",
        ["-6", "neigh", "replace", "proxy", CT_IPV6, "dev", HOST_IF],
    )?;
    run(
        "ip",
        [
            "-6",
            "route",
            "replace",
            &format!("{}/128", CT_IPV6),
            "dev",
            VETH,
        ],
    )?;
    Ok(())
}

fn incus_exists(name: &str) -> Result<bool> {
    let output = Command::new("incus")
        .args(["info", name])
        .output()
        .context("failed to query incus instance")?;
    Ok(output.status.success())
}

fn incus_is_running(name: &str) -> Result<bool> {
    let output = Command::new("incus")
        .args(["info", name])
        .output()
        .context("failed to query incus instance")?;
    if !output.status.success() {
        return Ok(false);
    }
    let text = String::from_utf8_lossy(&output.stdout);
    Ok(text.lines().any(|line| line.trim() == "Status: RUNNING"))
}

fn incus_pid(name: &str) -> Result<u32> {
    let output = Command::new("incus")
        .args(["info", name])
        .output()
        .context("failed to query incus instance")?;
    if !output.status.success() {
        bail!("no PID for {}", name);
    }
    let text = String::from_utf8_lossy(&output.stdout);
    for line in text.lines() {
        let line = line.trim();
        if let Some(pid) = line.strip_prefix("PID:") {
            let pid = pid.trim().parse::<u32>().context("invalid incus PID")?;
            return Ok(pid);
        }
    }
    bail!("no PID for {}", name)
}

fn run(cmd: &str, args: impl IntoIterator<Item = impl AsRef<std::ffi::OsStr>>) -> Result<()> {
    let args_vec: Vec<_> = args
        .into_iter()
        .map(|a| a.as_ref().to_os_string())
        .collect();
    let status = Command::new(cmd)
        .args(&args_vec)
        .stdin(Stdio::null())
        .status()
        .with_context(|| format!("failed to execute {}", cmd))?;
    if !status.success() {
        bail!("{} {:?} failed with {}", cmd, args_vec, status);
    }
    Ok(())
}

fn run_ignore(cmd: &str, args: impl IntoIterator<Item = impl AsRef<std::ffi::OsStr>>) {
    let _ = run(cmd, args);
}

fn unload_own_xdp_program(ifname: &str) -> Result<()> {
    let output = Command::new("xdp-loader")
        .args(["status", ifname])
        .output()
        .with_context(|| format!("failed to inspect XDP status for {}", ifname))?;

    if !output.status.success() {
        return Ok(());
    }

    let stdout = String::from_utf8_lossy(&output.stdout);
    let Some(line) = stdout
        .lines()
        .find(|line| line.split_whitespace().any(|token| token == XDP_PROG_NAME))
    else {
        return Ok(());
    };

    let tokens: Vec<_> = line.split_whitespace().collect();
    let Some(prog_pos) = tokens.iter().position(|token| *token == XDP_PROG_NAME) else {
        return Ok(());
    };
    let Some(id_token) = tokens.get(prog_pos + 1) else {
        return Ok(());
    };
    let id = id_token
        .parse::<u32>()
        .with_context(|| format!("invalid XDP program id in status line: {}", line))?;

    run_ignore("xdp-loader", ["unload", ifname, "--id", &id.to_string()]);
    Ok(())
}

//! Host-level privacy network provisioning — OVS switching fabric only.
//
// Current architecture (Artix Linux + s6 + Incus + rovs):
// - Host runs ovsbr0 via OVSDB (datapath=system or netdev for AF_XDP)
// - All privacy services (Xray, mail) run inside Incus containers
// - Containers have NO host interface — they communicate via Unix sockets
//   through OVS internal ports using OpenFlow routing
// - Xray ingress lives in wg-xray Incus container, NOT on host
// - OpenFlow controller (also in wg-xray container) drives forwarding
// - priv_* internal ports are created by ovs-attach-ports.sh

use anyhow::{Context, Result};
use op_network::{openflow::OpenFlowClient, OvsdbDbusClient};
use std::path::Path;
use tracing::{info, warn};

const DEFAULT_BRIDGE: &str = "ovsbr0";
const DEFAULT_PRIVACY_PORTS: &[&str] = &[
    "gbr_xray",
    "gbr_warp",
    "gbr_wg",
    "ovsbr0-mgmt",
    "ovsbr0-sock",
];
const DEFAULT_MGMT_CIDR: &str = "10.200.0.1/24"; // Xray ingress IP (inside wg-xray container)
const DEFAULT_OPENFLOW_CONTROLLER: &str = "10.200.0.1:6653"; // Controller inside wg-xray
const DEFAULT_DATAPATH_TYPE: &str = "system";
const DEFAULT_FAIL_MODE: &str = "standalone";

#[derive(Debug, Clone)]
pub struct PrivacyNetworkHostConfig {
    pub bridge_name: String,
    pub privacy_ports: Vec<String>,
    pub management_cidr: String,
    pub openflow_controller: String,
    pub xray_ingress_ip: String,
    pub datapath_type: String,
    pub fail_mode: String,
}

impl PrivacyNetworkHostConfig {
    pub fn from_env() -> Self {
        Self {
            bridge_name: std::env::var("PRIVACY_BRIDGE_NAME")
                .unwrap_or_else(|_| DEFAULT_BRIDGE.to_string()),
            privacy_ports: std::env::var("PRIVACY_PORTS")
                .map(|s| s.split(',').map(|s| s.trim().to_string()).collect())
                .unwrap_or_else(|_| {
                    DEFAULT_PRIVACY_PORTS
                        .iter()
                        .map(|&s| s.to_string())
                        .collect()
                }),
            management_cidr: std::env::var("PRIVACY_MGMT_CIDR")
                .unwrap_or_else(|_| DEFAULT_MGMT_CIDR.to_string()),
            openflow_controller: std::env::var("PRIVACY_OPENFLOW_CONTROLLER")
                .unwrap_or_else(|_| DEFAULT_OPENFLOW_CONTROLLER.to_string()),
            xray_ingress_ip: std::env::var("XRAY_INGRESS_IP")
                .unwrap_or_else(|_| "10.200.0.1".to_string()),
            datapath_type: std::env::var("PRIVACY_DATAPATH_TYPE")
                .unwrap_or_else(|_| DEFAULT_DATAPATH_TYPE.to_string()),
            fail_mode: std::env::var("PRIVACY_FAIL_MODE")
                .unwrap_or_else(|_| DEFAULT_FAIL_MODE.to_string()),
        }
    }
}

/// Ensure host privacy network topology exists for wgcf architecture.
///
/// This is called during magic link verification to ensure the network
/// is ready for new users.
pub async fn ensure_host_privacy_network() -> Result<()> {
    let cfg = PrivacyNetworkHostConfig::from_env();
    ensure_host_privacy_network_with_config(&cfg).await
}

async fn ensure_host_privacy_network_with_config(cfg: &PrivacyNetworkHostConfig) -> Result<()> {
    info!(
        "Ensuring OVS privacy fabric: bridge={} ports={:?}",
        cfg.bridge_name, cfg.privacy_ports
    );

    let ovs = OvsdbDbusClient::new();

    // Verify OVSDB connectivity
    ovs.list_dbs()
        .await
        .context("Open vSwitch DB is unavailable; cannot provision privacy network")?;

    // The bridge should be created by netplan/op-ovsbr0-setup, but ensure it exists
    if !ovs
        .bridge_exists(&cfg.bridge_name)
        .await
        .context("Failed to check bridge existence")?
    {
        info!("Bridge {} not found, creating via OVSDB", cfg.bridge_name);
        ovs.create_bridge(&cfg.bridge_name)
            .await
            .with_context(|| format!("Failed to create OVS bridge '{}'", cfg.bridge_name))?;
    }

    // Configure bridge for controller-driven forwarding. AF_XDP cutover sets
    // PRIVACY_DATAPATH_TYPE=netdev so this path does not undo the datapath.
    info!(
        "Configuring {} datapath_type={} fail_mode={}",
        cfg.bridge_name, cfg.datapath_type, cfg.fail_mode
    );
    ovs.set_bridge_property(&cfg.bridge_name, "datapath_type", &cfg.datapath_type)
        .await
        .with_context(|| format!("Failed to set bridge datapath_type={}", cfg.datapath_type))?;
    ovs.set_bridge_property(&cfg.bridge_name, "fail_mode", &cfg.fail_mode)
        .await
        .with_context(|| format!("Failed to set bridge fail_mode={}", cfg.fail_mode))?;

    let existing_ports = ovs
        .list_bridge_ports(&cfg.bridge_name)
        .await
        .context("Failed to list bridge ports")?;

    // NOTE: wgcf/Xray run inside Incus containers (wg-xray), not as host interfaces.
    // Container traffic reaches the bridge via Unix sockets + OpenFlow routing.
    // Do NOT attach wgcf as a host port — it does not exist on the host.

    // Ensure all privacy internal ports exist (created by ovs-attach-ports.sh)
    for port in &cfg.privacy_ports {
        if !existing_ports.iter().any(|p| p == port) {
            ovs.add_port_with_type(&cfg.bridge_name, port, Some("internal"))
                .await
                .with_context(|| format!("Failed to add internal port '{}'", port))?;
            info!("Added internal port: {}", port);
        }
    }

    // Bring up host bridge only (containers have no host interfaces)
    if Path::new(&format!("/sys/class/net/{}", cfg.bridge_name)).exists() {
        op_network::rtnetlink::link_up(&cfg.bridge_name)
            .await
            .with_context(|| format!("Failed to bring up interface {}", cfg.bridge_name))?;
    }

    // Bring up privacy internal ports
    for port in &cfg.privacy_ports {
        if Path::new(&format!("/sys/class/net/{}", port)).exists() {
            op_network::rtnetlink::link_up(port)
                .await
                .with_context(|| format!("Failed to bring up port {}", port))?;
        }
    }

    // Verify Xray ingress is available on the management IP
    // NOTE: Xray runs inside the wg-xray Incus container, not on the host.
    // The management IP is reachable through OVS internal ports + OpenFlow.
    info!(
        "Privacy network ready. Xray ingress (in wg-xray container) should be listening on {}",
        cfg.xray_ingress_ip
    );

    // Probe OpenFlow controller if available
    // NOTE: Controller runs inside wg-xray container, reachable via OVS tunnel.
    if let Ok(controller_addr) = cfg.openflow_controller.parse::<std::net::SocketAddr>() {
        match OpenFlowClient::connect(controller_addr).await {
            Ok(_) => info!("OpenFlow controller reachable (via container path)"),
            Err(e) => warn!("OpenFlow controller not ready yet: {}", e),
        }
    }

    info!("OVS privacy fabric provisioning complete (containerized services via Unix sockets)");
    Ok(())
}

//! Zeroclaw / Antigravity proxy handlers
//!
//! Proxies chat requests to the antigravity Python SDK bot running on
//! 127.0.0.1:8081, and serves the combined schema (OpenAPI + zeroclaw
//! projection) for schema-driven UI rendering.

use axum::{body::Body, extract::Extension, http::StatusCode, response::Response, Json};
use serde::Deserialize;
use simd_json::prelude::*;
use simd_json::{json, OwnedValue as Value};
use std::sync::Arc;
use tracing::{error, info};

use crate::state::AppState;

/// Antigravity bridge base URL - defaults to standard Antigravity IDE bridge port
/// Can be overridden with ANTIGRAVITY_BRIDGE_URL env var
fn antigravity_base() -> String {
    std::env::var("ANTIGRAVITY_BRIDGE_URL").unwrap_or_else(|_| "http://127.0.0.1:3333".to_string())
}

/// Get WireGuard identity for auth headers
fn wireguard_identity_headers() -> Vec<(&'static str, String)> {
    let mut headers = Vec::new();

    // X-WireGuard-Pubkey from environment (set by wg-xray container or host)
    if let Ok(pubkey) = std::env::var("WG_PUBKEY") {
        headers.push(("X-WireGuard-Pubkey", pubkey));
    }

    // X-Ghostbridge-Trace-ID for accountability loop
    if let Ok(trace_id) = std::env::var("GHOSTBRIDGE_TRACE_ID") {
        headers.push(("X-Ghostbridge-Trace-ID", trace_id));
    }

    // Container-scoped identity for wg-xray
    if let Ok(container_id) = std::env::var("CONTAINER_ID") {
        headers.push(("X-Container-ID", container_id));
    }

    headers
}

/// Schema-driven chat request — shape matches the antigravity bot's
/// `ChatRequest` so we can forward verbatim.
#[derive(Debug, Deserialize)]
pub struct ZeroclawChatRequest {
    pub message: String,
    #[serde(default)]
    pub session_id: Option<String>,
    #[serde(default)]
    pub provider: Option<String>,
    #[serde(default)]
    pub model: Option<String>,
}

/// Proxy chat request to the antigravity bot.
/// POST /api/zeroclaw/chat
pub async fn zeroclaw_chat_handler(
    Extension(_state): Extension<Arc<AppState>>,
    Json(req): Json<ZeroclawChatRequest>,
) -> Response {
    let client = match reqwest::Client::builder()
        .timeout(std::time::Duration::from_secs(120))
        .build()
    {
        Ok(c) => c,
        Err(e) => {
            error!("Failed to build HTTP client: {}", e);
            return json_error_response(
                StatusCode::INTERNAL_SERVER_ERROR,
                "Failed to build HTTP client",
            );
        }
    };

    let url = format!("{}/api/chat", antigravity_base());

    let body = json!({
        "message": req.message,
        "session_id": req.session_id,
        "provider": req.provider,
        "model": req.model,
    });

    info!(
        "Proxying zeroclaw chat to antigravity bot: {} chars",
        req.message.len()
    );

    let mut request_builder = client.post(&url).header("Content-Type", "application/json");

    // Add WireGuard identity headers for auth
    for (key, value) in wireguard_identity_headers() {
        request_builder = request_builder.header(key, value);
    }

    match request_builder
        .body(simd_json::to_string(&body).unwrap_or_default())
        .send()
        .await
    {
        Ok(resp) => {
            let status = resp.status();
            let body_bytes = match resp.bytes().await {
                Ok(b) => b,
                Err(e) => {
                    error!("Failed to read antigravity response body: {}", e);
                    return json_error_response(
                        StatusCode::BAD_GATEWAY,
                        "Failed to read antigravity response",
                    );
                }
            };

            let axum_status =
                StatusCode::from_u16(status.as_u16()).unwrap_or(StatusCode::BAD_GATEWAY);
            Response::builder()
                .status(axum_status)
                .header("Content-Type", "application/json")
                .body(Body::from(body_bytes))
                .unwrap_or_else(|_| {
                    json_error_response(
                        StatusCode::INTERNAL_SERVER_ERROR,
                        "Failed to build response",
                    )
                })
        }
        Err(e) => {
            error!("Antigravity bot unreachable: {}", e);
            json_error_response(
                StatusCode::BAD_GATEWAY,
                &format!("Antigravity bot unreachable: {}", e),
            )
        }
    }
}

/// Proxy streaming chat request to the antigravity bot SSE endpoint.
/// POST /api/zeroclaw/chat/stream
pub async fn zeroclaw_chat_stream_handler(
    Extension(_state): Extension<Arc<AppState>>,
    Json(req): Json<ZeroclawChatRequest>,
) -> Response {
    let client = match reqwest::Client::builder()
        .timeout(std::time::Duration::from_secs(300))
        .build()
    {
        Ok(c) => c,
        Err(e) => {
            error!("Failed to build HTTP client: {}", e);
            return json_error_response(
                StatusCode::INTERNAL_SERVER_ERROR,
                "Failed to build HTTP client",
            );
        }
    };

    let url = format!("{}/api/chat/stream", antigravity_base());

    let body = json!({
        "message": req.message,
        "session_id": req.session_id,
        "provider": req.provider,
        "model": req.model,
    });

    info!(
        "Proxying zeroclaw chat stream to antigravity bot: {} chars",
        req.message.len()
    );

    let mut request_builder = client
        .post(&url)
        .header("Content-Type", "application/json")
        .header("Accept", "text/event-stream");

    // Add WireGuard identity headers for auth
    for (key, value) in wireguard_identity_headers() {
        request_builder = request_builder.header(key, value);
    }

    match request_builder
        .body(simd_json::to_string(&body).unwrap_or_default())
        .send()
        .await
    {
        Ok(resp) => {
            let status = resp.status();
            let body_bytes = match resp.bytes().await {
                Ok(b) => b,
                Err(e) => {
                    error!("Failed to read antigravity stream body: {}", e);
                    return json_error_response(
                        StatusCode::BAD_GATEWAY,
                        "Failed to read antigravity stream",
                    );
                }
            };

            let axum_status =
                StatusCode::from_u16(status.as_u16()).unwrap_or(StatusCode::BAD_GATEWAY);
            Response::builder()
                .status(axum_status)
                .header("Content-Type", "text/event-stream")
                .header("Cache-Control", "no-cache")
                .body(Body::from(body_bytes))
                .unwrap_or_else(|_| {
                    json_error_response(
                        StatusCode::INTERNAL_SERVER_ERROR,
                        "Failed to build stream response",
                    )
                })
        }
        Err(e) => {
            error!("Antigravity bot unreachable: {}", e);
            json_error_response(
                StatusCode::BAD_GATEWAY,
                &format!("Antigravity bot unreachable: {}", e),
            )
        }
    }
}

/// Helper to build a JSON error response.
fn json_error_response(status: StatusCode, message: &str) -> Response {
    let body = simd_json::to_string(&json!({"error": message})).unwrap_or_default();
    Response::builder()
        .status(status)
        .header("Content-Type", "application/json")
        .body(Body::from(body))
        .unwrap_or_else(|_| {
            Response::builder()
                .status(StatusCode::INTERNAL_SERVER_ERROR)
                .body(Body::empty())
                .expect("empty body should always succeed")
        })
}

/// Read zeroclaw schema directly from shared memory (Absolute Base)
/// Per AGENTS.md: "The Absolute Base: PluginSchema is the single source of truth"
fn read_zeroclaw_from_shm() -> Option<Value> {
    use std::fs;

    const SHM_SCHEMA_PATH: &str = "/dev/shm/live-schema.json";

    let content = fs::read_to_string(SHM_SCHEMA_PATH).ok()?;
    let mut bytes = content.into_bytes();
    let schema: Value = simd_json::to_owned_value(&mut bytes).ok()?;

    // Extract zeroclaw from the schema examples (the canonical source)
    let zeroclaw_schema = schema.get("zeroclaw")?.as_array()?.first()?;
    let fields = zeroclaw_schema.get("fields")?.as_array()?;

    // Helper: find field example by name
    fn find_example(fields: &[Value], name: &str) -> Option<Value> {
        for f in fields {
            let field_name = f.get("name")?.as_str()?;
            if field_name == name {
                return f.get("example").cloned();
            }
        }
        None
    }

    Some(json!({
        "active": true,
        "status": find_example(fields, "status").and_then(|v| v.as_str().map(String::from)).unwrap_or_else(|| "declared".to_string()),
        "selected_provider": find_example(fields, "selected_provider").and_then(|v| v.as_str().map(String::from)).unwrap_or_else(|| "antigravity".to_string()),
        "selected_model": find_example(fields, "selected_model").and_then(|v| v.as_str().map(String::from)).unwrap_or_else(|| "gemini-2.5-flash".to_string()),
        "providers": find_example(fields, "providers")?,
        "model_routes": find_example(fields, "model_routes")?,
        "router": find_example(fields, "router")?,
        "tools": find_example(fields, "tools")?,
        "structured_output": find_example(fields, "structured_output")?,
        "transport": find_example(fields, "transport")?,
        "ui_surfaces": find_example(fields, "ui_surfaces")?,
    }))
}

/// Serve the combined schema for schema-driven UI rendering.
///
/// Merges the antigravity bot's OpenAPI schema with the zeroclaw plugin
/// projection (providers, model_routes, tools, structured_output) so the
/// frontend can render the entire chat interface from a single schema.
/// GET /api/zeroclaw/schema
pub async fn zeroclaw_schema_handler(Extension(state): Extension<Arc<AppState>>) -> Response {
    // Fetch antigravity OpenAPI schema
    let client = match reqwest::Client::builder()
        .timeout(std::time::Duration::from_secs(10))
        .build()
    {
        Ok(c) => c,
        Err(e) => {
            error!("Failed to build HTTP client: {}", e);
            return json_error_response(
                StatusCode::INTERNAL_SERVER_ERROR,
                "Failed to build HTTP client",
            );
        }
    };

    let openapi = match client
        .get(format!("{}/openapi.json", antigravity_base()))
        .send()
        .await
    {
        Ok(resp) => match resp.json::<Value>().await {
            Ok(v) => v,
            Err(e) => {
                error!("Failed to parse antigravity OpenAPI: {}", e);
                json!({})
            }
        },
        Err(e) => {
            error!("Failed to fetch antigravity OpenAPI: {}", e);
            json!({})
        }
    };

    // Fetch zeroclaw from shared memory (Absolute Base) first
    // Per AGENTS.md: "1:1 Direct Read (Zero-Copy)" from /dev/shm
    let zeroclaw = if let Some(shm_data) = read_zeroclaw_from_shm() {
        info!("Using zeroclaw from shared memory (Absolute Base)");
        shm_data
    } else {
        // Fallback to D-Bus projection
        match crate::projection_client::get_projection(&state.projection_cache, "zeroclaw").await {
            Some(v) => v,
            None => {
                error!("Zeroclaw not available from shared memory or D-Bus");
                return json_error_response(
                    StatusCode::SERVICE_UNAVAILABLE,
                    "Zeroclaw projection not available",
                );
            }
        }
    };

    // Build a JSON Schema for the chat form from zeroclaw providers + model_routes
    let providers = zeroclaw
        .get("providers")
        .and_then(|v| v.as_array())
        .map(|arr| {
            arr.iter()
                .filter_map(|p| p.get("id").and_then(|v| v.as_str()).map(String::from))
                .collect::<Vec<_>>()
        })
        .unwrap_or_default();

    let model_routes = zeroclaw
        .get("model_routes")
        .and_then(|v| v.as_array())
        .map(|arr| {
            arr.iter()
                .filter_map(|r| {
                    let model = r.get("model").and_then(|v| v.as_str())?;
                    let hint = r.get("hint").and_then(|v| v.as_str());
                    let provider = r
                        .get("provider")
                        .and_then(|v| v.as_str())
                        .unwrap_or("unknown");
                    let available = r
                        .get("available")
                        .and_then(|v| v.as_bool())
                        .unwrap_or(false);

                    // Build label: "provider/model (hint) [status]"
                    let mut label = format!("{}/{}", provider, model);
                    if let Some(h) = hint {
                        label.push_str(&format!(" ({})", h));
                    }
                    if !available {
                        label.push_str(" [declared]");
                    }

                    Some(json!({"const": model, "title": label}))
                })
                .collect::<Vec<_>>()
        })
        .unwrap_or_default();

    let chat_schema = json!({
        "$schema": "http://json-schema.org/draft-07/schema#",
        "type": "object",
        "title": "Zeroclaw Chat",
        "properties": {
            "provider": {
                "type": "string",
                "enum": providers,
                "description": "LLM provider route"
            },
            "model": {
                "type": "string",
                "oneOf": model_routes,
                "description": "Model to use for this turn"
            },
            "message": {
                "type": "string",
                "description": "Chat message",
                "minLength": 1
            }
        },
        "required": ["message"]
    });

    let schema = json!({
        "openapi": openapi,
        "zeroclaw": {
            "plugin_state": zeroclaw,
            "chat_form_schema": chat_schema,
            "structured_output": zeroclaw.get("structured_output").cloned().unwrap_or(json!({})),
            "tools": zeroclaw.get("tools").cloned().unwrap_or(json!([])),
        }
    });

    let body = simd_json::to_string(&schema).unwrap_or_default();
    Response::builder()
        .status(StatusCode::OK)
        .header("Content-Type", "application/json")
        .body(Body::from(body))
        .unwrap_or_else(|_| {
            json_error_response(
                StatusCode::INTERNAL_SERVER_ERROR,
                "Failed to build schema response",
            )
        })
}

//! ovs-attach — D-Bus client that calls BringUpLoopback and AttachPort
//! for container bootstrap.
//!
//! Discovers all config from the D-Bus tree under:
//! - /org/opdbus/v1/plugin/plugins/oci (loopback_required, port_attach per container)
//! - /org/opdbus/v1/plugin/plugins/privacy_router (bridge, port, IPs — fallback)
//!
//! No hardcoded bus names, paths, or IP addresses. The schema IS the config.

use anyhow::{Context, Result};
use serde_json::Value;
use std::path::Path;
use std::process::Command;
use std::thread;
use std::time::Duration;
use zbus::connection::Builder;

const DBUS_SOCKET: &str = "/run/op-dbus.sock";
const PLUGIN_BUS: &str = "org.opdbus.v1";
const PRIVACY_ROUTER_BASE: &str = "/org/opdbus/v1/plugin/plugins/privacy_router";
const OCI_BASE: &str = "/org/opdbus/v1/plugin/plugins/oci";

async fn get_json_property(conn: &zbus::Connection, path: &str, prop: &str) -> Result<Value> {
    let iface = "org.opdbus.ProjectedObjectV1".to_string();
    let msg = conn
        .call_method(
            Some(PLUGIN_BUS),
            path,
            Some("org.freedesktop.DBus.Properties"),
            "Get",
            &(&iface, prop),
        )
        .await?;
    let body = msg.body();
    let reply: zbus::zvariant::Value = body.deserialize()?;

    if let zbus::zvariant::Value::Str(s) = reply {
        Ok(serde_json::from_str(&s)?)
    } else {
        anyhow::bail!("expected string property, got {:?}", reply)
    }
}

/// Discover the proxy path on the ovsdb daemon bus by introspecting the tree.
async fn discover_proxy_path(conn: &zbus::Connection, dbus_bus: &str) -> Result<String> {
    let tree_msg = conn
        .call_method(
            Some(dbus_bus),
            "/",
            Some("org.freedesktop.DBus.Introspectable"),
            "Introspect",
            &(),
        )
        .await?;
    let introspect_xml: String = tree_msg.body().deserialize()?;

    if introspect_xml.contains("opdbus") {
        let rovs_msg = conn
            .call_method(
                Some(dbus_bus),
                "/org/opdbus/rovs",
                Some("org.freedesktop.DBus.Introspectable"),
                "Introspect",
                &(),
            )
            .await?;
        let rovs_xml: String = rovs_msg.body().deserialize()?;

        if rovs_xml.contains("proxy") {
            return Ok("/org/opdbus/rovs/proxy".to_string());
        }
    }
    anyhow::bail!("could not find proxy node in ovsdb daemon tree")
}

/// Read this container's config from the OCI plugin schema.
/// Returns (loopback_required, port_attach_config).
async fn read_oci_container_config(
    conn: &zbus::Connection,
    instance_name: &str,
) -> Result<(bool, Option<Value>)> {
    let oci_schema = get_json_property(conn, OCI_BASE, "JsonData").await?;

    if let Some(containers) = oci_schema["config"]["containers"].as_array() {
        for c in containers {
            if c["name"].as_str() == Some(instance_name) {
                let lo = c["loopback_required"].as_bool().unwrap_or(false);
                let port = c.get("port_attach").cloned();
                return Ok((lo, port));
            }
        }
    }
    Ok((false, None))
}

#[tokio::main]
async fn main() -> Result<()> {
    // Wait for D-Bus socket
    eprintln!("waiting for D-Bus socket at {DBUS_SOCKET}...");
    for _ in 0..60 {
        if Path::new(DBUS_SOCKET).exists() {
            break;
        }
        thread::sleep(Duration::from_secs(1));
    }
    anyhow::ensure!(
        Path::new(DBUS_SOCKET).exists(),
        "D-Bus socket not found after 60s"
    );

    // Connect to D-Bus
    let address = format!("unix:path={DBUS_SOCKET}");
    eprintln!("connecting to D-Bus...");
    let conn = Builder::address(&*address)?
        .build()
        .await
        .context("connect to D-Bus")?;

    // Read instance name from hostname (incus sets hostname = instance name)
    let instance_name = std::fs::read_to_string("/etc/hostname")
        .unwrap_or_default()
        .trim()
        .to_string();
    if instance_name.is_empty() {
        anyhow::bail!("could not read /etc/hostname for instance name");
    }
    eprintln!("instance_name={instance_name}");

    // ── Step 1: Read this container's config from the OCI plugin schema ──
    eprintln!("reading OCI plugin schema from D-Bus tree...");
    let (loopback_required, port_attach_config) = read_oci_container_config(&conn, &instance_name)
        .await
        .unwrap_or((false, None));

    // ── Step 2: Bring up loopback if the OCI schema declares it ────────
    if loopback_required {
        eprintln!("loopback_required=true for {instance_name}, calling BringUpLoopback...");

        let daemon = get_json_property(
            &conn,
            "/org/opdbus/v1/plugin/plugins/ovsdb_daemon",
            "JsonData",
        )
        .await?;
        let dbus_bus = daemon["dbus_bus_name"]
            .as_str()
            .unwrap_or("org.opdbus.v1.plugins.ovsdb");
        let proxy_path = discover_proxy_path(&conn, dbus_bus).await?;

        let lo_params = serde_json::json!({
            "instance_name": instance_name
        });

        let lo_result: String = conn
            .call_method(
                Some(dbus_bus),
                proxy_path.as_str(),
                Some("org.opdbus.rovs.proxy"),
                "BringUpLoopback",
                &(lo_params.to_string()),
            )
            .await?
            .body()
            .deserialize()?;

        eprintln!("BringUpLoopback result: {lo_result}");
    } else {
        eprintln!("loopback_required=false for {instance_name}, skipping lo bring-up");
    }

    // ── Step 3: Attach OVS port ─────────────────────────────────────────
    // If the OCI schema has port_attach config, use it directly.
    // Otherwise fall back to the privacy_router schema for the xray container.
    let (params, bridge, socket_port) = if let Some(pa) = &port_attach_config {
        let bridge = pa["bridge"].as_str().unwrap_or("ovsbr0").to_string();
        let iface_name = pa["iface_name"].as_str().unwrap_or("gbr_xray").to_string();
        let ip_addrs: Vec<Value> = pa["ip_addrs"].as_array().cloned().unwrap_or_default();
        let gateway = pa["gateway"].as_str().map(String::from);
        let routes: Vec<Value> = pa["routes"].as_array().cloned().unwrap_or_default();

        let p = serde_json::json!({
            "port_name": format!("c_{}", iface_name),
            "bridge": bridge,
            "instance_name": instance_name,
            "iface_name": iface_name,
            "ip_addrs": ip_addrs,
            "gateway": gateway,
            "routes": routes
        });
        (p, bridge.clone(), iface_name)
    } else {
        // Fallback: read from privacy_router schema (for the wg-xray container)
        eprintln!("reading privacy_router schema from D-Bus tree...");
        let schema = get_json_property(&conn, PRIVACY_ROUTER_BASE, "JsonData").await?;

        let bridge = schema["config"]["bridge_name"]
            .as_str()
            .unwrap_or("ovsbr0")
            .to_string();
        let socket_port = schema["config"]["xray"]["socket_port"]
            .as_str()
            .unwrap_or("gbr_xray")
            .to_string();
        let container_id = schema["config"]["xray"]["container_id"]
            .as_u64()
            .unwrap_or(101);

        eprintln!("bridge={bridge}, socket_port={socket_port}, container_id={container_id}");

        let p = serde_json::json!({
            "port_name": format!("c{}_{}", container_id, socket_port),
            "bridge": bridge,
            "instance_name": instance_name,
            "iface_name": socket_port,
            "ip_addrs": ["10.200.0.1/30", "10.0.0.2/24"],
            "gateway": "10.200.0.2",
            "routes": ["10.0.0.1 via 10.200.0.2"]
        });
        (p, bridge, socket_port)
    };

    // Check if interface already exists
    if Command::new("ip")
        .args(["link", "show", &socket_port])
        .output()
        .is_ok_and(|o| o.status.success())
    {
        eprintln!("interface {socket_port} already exists, skipping AttachPort");
        return Ok(());
    }

    // Discover AttachPort method location
    let daemon = get_json_property(
        &conn,
        "/org/opdbus/v1/plugin/plugins/ovsdb_daemon",
        "JsonData",
    )
    .await?;
    let dbus_bus = daemon["dbus_bus_name"]
        .as_str()
        .unwrap_or("org.opdbus.v1.plugins.ovsdb");
    let proxy_path = discover_proxy_path(&conn, dbus_bus).await?;

    eprintln!("discovered AttachPort at bus={dbus_bus} path={proxy_path}");

    // Call AttachPort
    eprintln!("calling AttachPort...");
    let result: String = conn
        .call_method(
            Some(dbus_bus),
            proxy_path.as_str(),
            Some("org.opdbus.rovs.proxy"),
            "AttachPort",
            &(params.to_string()),
        )
        .await?
        .body()
        .deserialize()?;

    eprintln!("AttachPort result: {result}");

    let parsed: Value = serde_json::from_str(&result)?;
    if parsed["success"].as_bool() != Some(true) {
        anyhow::bail!("AttachPort failed: {}", parsed["message"]);
    }

    // Wait for interface to appear
    eprintln!("waiting for interface {socket_port}...");
    for _ in 0..30 {
        if Command::new("ip")
            .args(["link", "show", &socket_port])
            .output()
            .is_ok_and(|o| o.status.success())
        {
            eprintln!("interface {socket_port} is up");
            return Ok(());
        }
        thread::sleep(Duration::from_secs(1));
    }

    anyhow::bail!("interface {socket_port} not found after 30s")
}

